      WHERE {
        ?obs_low a sosa:Observation ;
          sosa:resultTime ?t_low ;
          sosa:hasResult ?elev_low .
        ?elev_low qudt:numericValue ?num_low .
        ?obs_low hydrorwth:monitorsCatchment ?station_low .
        ?station_low geo:hasGeometry ?geom_low .
        ?geom_low a sf:Point .
      }
      ORDER BY ASC(?num_low)
      LIMIT 1
    }
    BIND(
      geof:distance(?geom_high, ?geom_low) AS ?distance
    )
  }
}

